/* Catalog request form. SYNTHETIC FIXTURE written for this lab.
   Used only by templates/addons/catalog_request/blocks/catalog_request_form.tpl. */
.ty-catalog-request {
    width: 760px;
    margin: 24px auto;
    padding: 24px 28px;
    border: 1px solid #d5d9de;
    background: #ffffff;
}
.ty-catalog-request__title {
    margin: 0 0 6px;
    font-size: 22px;
}
.ty-catalog-request__intro {
    margin: 0 0 18px;
    color: #55606b;
}
.ty-catalog-request__row {
    display: flex;
    gap: 16px;
}
.ty-catalog-request__field {
    flex: none;
    width: 230px;
}
.ty-catalog-request__field--wide {
    width: 476px;
}
.ty-catalog-request__field .ty-input-text {
    width: 214px;
}
.ty-catalog-request__field--wide .ty-input-text {
    width: 460px;
}
.ty-catalog-request__choices {
    margin: 8px 0 18px;
    padding: 0;
    border: 0;
    white-space: nowrap;
}
.ty-catalog-request__choices label {
    margin-right: 22px;
}
.ty-catalog-request__buttons {
    text-align: right;
}

